// Guitar Trainer color palette (bunny.net inspired)

// Primary blues
$gt-primary-blue: #183d6d;
$gt-primary-dark: #052740;
$gt-primary-darker: #051e38;

// Accent orange (gradient endpoints)
$gt-accent-orange: #fd8d32;
$gt-accent-orange-light: #ffaf48;

// Neutrals
$gt-neutral-white: #ffffff;
$gt-neutral-light: #e6e8ea;
$gt-neutral-mid: #979797;

// Typography
$gt-font-family: ui-sans-serif, system-ui, sans-serif;

// Layout
$gt-max-width: 1140px;
$gt-border-radius: 0.8rem;

@use 'variables' as gt;

// Light theme overrides for Taiga UI CSS custom properties
[tuiTheme='light'] {
  // Backgrounds
  --tui-background-base: #{gt.$gt-neutral-white};
  --tui-background-base-alt: #{gt.$gt-neutral-light};
  --tui-background-accent-1: #{gt.$gt-primary-blue};
  --tui-background-accent-1-hover: #{gt.$gt-primary-dark};
  --tui-background-accent-1-pressed: #{gt.$gt-primary-darker};
  --tui-background-accent-2: #{gt.$gt-accent-orange};
  --tui-background-accent-2-hover: #{gt.$gt-accent-orange-light};
  --tui-background-accent-2-pressed: #{gt.$gt-accent-orange};
  --tui-background-elevation-1: #{gt.$gt-neutral-white};
  --tui-background-elevation-2: #{gt.$gt-neutral-white};

  // Text
  --tui-text-primary: #{gt.$gt-primary-darker};
  --tui-text-secondary: #{gt.$gt-primary-dark};
  --tui-text-tertiary: #{gt.$gt-neutral-mid};
  --tui-text-action: #{gt.$gt-primary-blue};
  --tui-text-action-hover: #{gt.$gt-primary-dark};

  // Custom Guitar Trainer variables
  --gt-primary: #{gt.$gt-primary-blue};
  --gt-primary-dark: #{gt.$gt-primary-dark};
  --gt-primary-darker: #{gt.$gt-primary-darker};
  --gt-accent: #{gt.$gt-accent-orange};
  --gt-accent-light: #{gt.$gt-accent-orange-light};
  --gt-neutral: #{gt.$gt-neutral-light};
  --gt-neutral-mid: #{gt.$gt-neutral-mid};
  --gt-text: #{gt.$gt-primary-darker};
  --gt-surface: #{gt.$gt-neutral-white};
}

// Dark theme overrides for Taiga UI CSS custom properties
[tuiTheme='dark'] {
  // Backgrounds
  --tui-background-base: #{gt.$gt-primary-darker};
  --tui-background-base-alt: #{gt.$gt-primary-dark};
  --tui-background-accent-1: #{gt.$gt-primary-blue};
  --tui-background-accent-1-hover: #2a5a9a;
  --tui-background-accent-1-pressed: #{gt.$gt-primary-dark};
  --tui-background-accent-2: #{gt.$gt-accent-orange};
  --tui-background-accent-2-hover: #{gt.$gt-accent-orange-light};
  --tui-background-accent-2-pressed: #{gt.$gt-accent-orange};
  --tui-background-elevation-1: #{gt.$gt-primary-dark};
  --tui-background-elevation-2: #0a3050;
  --tui-background-elevation-3: #{gt.$gt-primary-blue};

  // Text
  --tui-text-primary: #{gt.$gt-neutral-white};
  --tui-text-secondary: #{gt.$gt-neutral-light};
  --tui-text-tertiary: #{gt.$gt-neutral-mid};
  --tui-text-action: #{gt.$gt-accent-orange-light};
  --tui-text-action-hover: #{gt.$gt-accent-orange};

  // Borders
  --tui-border-normal: rgba(255, 255, 255, 0.14);
  --tui-border-hover: rgba(255, 255, 255, 0.6);

  // Custom Guitar Trainer variables
  --gt-primary: #{gt.$gt-primary-blue};
  --gt-primary-dark: #{gt.$gt-primary-dark};
  --gt-primary-darker: #{gt.$gt-primary-darker};
  --gt-accent: #{gt.$gt-accent-orange};
  --gt-accent-light: #{gt.$gt-accent-orange-light};
  --gt-neutral: rgba(255, 255, 255, 0.1);
  --gt-neutral-mid: #{gt.$gt-neutral-mid};
  --gt-text: #{gt.$gt-neutral-white};
  --gt-surface: #{gt.$gt-primary-dark};
}

@use '@taiga-ui/core/styles/taiga-ui-local';
@use 'app/theme/theme';
@use 'app/theme/variables' as gt;

body {
  margin: 0;
  font-family: gt.$gt-font-family;
}

