// Guitar Trainer color palette (bunny.net inspired)

// Primary blues
$primary-blue: #183d6d;
$primary-dark: #052740;
$primary-darker: #051e38;
$primary-blue-light: #2a5a9a;

// Accent orange (gradient endpoints)
$accent-orange: #fd8d32;
$accent-orange-light: #ffaf48;

// Neutrals
$neutral-white: #ffffff;
$neutral-light: #e6e8ea;
$neutral-mid: #979797;

// Dark theme specific
$dark-elevation-2: #0a3050;
$dark-border-normal: rgba(255, 255, 255, 0.14);
$dark-neutral-subtle: rgba(255, 255, 255, 0.1);

// Typography
$font-family: ui-sans-serif, system-ui, sans-serif;

// Layout
$max-width: 1140px;
$border-radius: 0.8rem;

@use 'variables' as gt;

// Light theme overrides for Taiga UI CSS custom properties
[tuiTheme='light'] {
  // Backgrounds
  --tui-background-base: #{gt.$neutral-white};
  --tui-background-base-alt: #{gt.$neutral-light};
  --tui-background-accent-1: #{gt.$primary-blue};
  --tui-background-accent-1-hover: #{gt.$primary-dark};
  --tui-background-accent-1-pressed: #{gt.$primary-darker};
  --tui-background-accent-2: #{gt.$accent-orange};
  --tui-background-accent-2-hover: #{gt.$accent-orange-light};
  --tui-background-accent-2-pressed: #{gt.$accent-orange};
  --tui-background-elevation-1: #{gt.$neutral-white};
  --tui-background-elevation-2: #{gt.$neutral-white};

  // Text
  --tui-text-primary: #{gt.$primary-darker};
  --tui-text-secondary: #{gt.$primary-dark};
  --tui-text-tertiary: #{gt.$neutral-mid};
  --tui-text-action: #{gt.$primary-blue};
  --tui-text-action-hover: #{gt.$primary-dark};

  // Custom Guitar Trainer variables
  --gt-primary: #{gt.$primary-blue};
  --gt-primary-dark: #{gt.$primary-dark};
  --gt-primary-darker: #{gt.$primary-darker};
